import sys; sys.path.insert(0,'.')
from helpers import *
from scipy.special import erf as serf
D=np.load('base_feats.npz'); y=D['y']; folds=np.load('folds.npy')
c11=D['cls11'].astype(np.float64); m11=D['mean11'].astype(np.float64)
T=np.eye(8)[y]
gelu=lambda u: 0.5*u*(1+serf(u/np.sqrt(2)))
def prep(c):
    x=c11+c*m11; xc=x-x.mean(1,keepdims=True); n=xc/xc.std(1,keepdims=True)
    Z=(n-n.mean(0))/(n.std(0)+1e-6); return Z@Z.T/768
def feat_cv(G,fn, lam, folds=folds):
    pred=np.zeros(len(y),int)
    for f in range(folds.max()+1):
        tr=folds!=f; P=fn(G[:,tr]); Ptr=P[tr]; pm=Ptr.mean(0); A=Ptr-pm
        a=np.linalg.solve(A@A.T+lam*np.eye(len(A)),T[tr]-T[tr].mean(0))
        pred[~tr]=np.argmax((P[~tr]-pm)@(A.T@a),1)
    return (pred==y).mean(), pred
for c in [1,2,4]:
    G=prep(c)
    for beta in [0.5,0.75,1.0,1.25]:
        fn=lambda g,b=beta: gelu(b*g)
        print('c',c,'beta',beta,[round(feat_cv(G,fn,l)[0],4) for l in [0.001,0.003,0.01,0.03]],flush=True)
